<?phpheader('Content-Type: text/html; charset=utf-8');class Database extends PDO{    public $pdo;    public $master_db;    public $current_user_id;    public $current_user_company_id;    private $debug = true;    public function debug($debug)    {        $this->debug = $debug;    }    public function __construct()    {        global $MasterDbName;        global $testMode;        $this->master_db = $MasterDbName;        $options = array(            PDO::ATTR_ERRMODE    => PDO::ERRMODE_SILENT,            PDO::ATTR_PERSISTENT => false,        );        try {            parent::__construct(DB_DSN, DB_USER, DB_PASSWORD,$options);            $this->query("SET NAMES utf8mb4");            $this->query("SET CHARACTER SET utf8mb4");        } catch (PDOException $e) {            print_r($e);            die();        }    }    public function GetToTable($sql, $array = array())    {        $sth = $this->prepare($sql);        foreach ($array as $key => $value) {            if ($key[0] == '@')                continue;            $sth->bindValue($key, $value);        }        $this->executeSth($sth, $sql, $array);        $datas = $sth->fetchAll(PDO::FETCH_ASSOC);        $e = $sth->errorInfo();        $sth->closeCursor();        $this->HasError($sql, $array, $sth);        return $datas;    }    public function SelectQuery($sql)    {        $sth = $this->prepare($sql);        $sth->execute();        return $sth->fetchAll(PDO::FETCH_ASSOC);    }    public function AffectedRows($sql, $array = array())    {        $sth = $this->prepare($sql);        foreach ($array as $key => $value) {            if ($key[0] == '@')                continue;            $sth->bindValue($key, $value);        }        $this->executeSth($sth, $sql, $array);        $this->UserLog($sql, json_encode(array_values($array), JSON_UNESCAPED_UNICODE));        $count = $sth->rowCount();        do {            $this->ErrorLog($sql, json_encode(array_values($array), JSON_UNESCAPED_UNICODE), $sth->errorInfo());        } while ($sth->nextRowset());        return $count;    }    public function AddToTable($sql, $array = array())    {        $sth = $this->prepare($sql);        foreach ($array as $key => $value) {            if ($key[0] == '@')                continue;            if (!isset($value))                $value = null;            $sth->bindValue($key, $value);        }        $this->executeSth($sth, $sql, $array);        $this->UserLog($sql, json_encode(array_values($array), JSON_UNESCAPED_UNICODE));        $count = $sth->rowCount();        $this->HasError($sql, $array, $sth);        return $count;    }    private function executeSth($sth, $sql, $array)    {        $time_start = microtime(true);        $return_sth = $sth->execute();        $time_end = microtime(true);        $query_time = $time_end - $time_start;        $this->ExecuteLog($sql, json_encode(array_values($array), JSON_UNESCAPED_UNICODE), $query_time);        return $return_sth;    }    public function UpdateToTable($sql, $array = array())    {        $sth = $this->prepare($sql);        foreach ($array as $key => $value) {            if ($key[0] == '@')                continue;            if (!isset($value))                $value = null;            $sth->bindValue($key, $value);        }        $updateStatus = $this->executeSth($sth, $sql, $array);        $this->UserLog($sql, json_encode(array_values($array), JSON_UNESCAPED_UNICODE));        $this->HasError($sql, $array, $sth);        if ($updateStatus) {            return true;        }        if ($sth->errorCode() == '42S22') {            return true;        }        return false;    }    public function AddDataToClassFromArray($class, $data)    {        if ($data) {            foreach ($data as $key => $value) {                if (property_exists($class, $key)) {                    $class->{$key} = $value;                }            }        }    }    public function CreateProcedureParamsFromClass($class, $explode = array(), $inout = array())    {        $array = [];        if ($class) {            foreach ($class as $key => $value) {                if ($key != 'db' && (empty($explode) || !in_array($key, $explode))) {                    $prm_key = !empty($inout) && in_array($key, $inout) ? '@prm_' . $key : ':prm_' . $key;                    $array[$prm_key] = $class->{$key};                }            }        }        return $array;    }    public function CreateProcedureSql($procedureName, $array = array())    {        $firstControl = true;        $sql = "CALL " . $procedureName . "( ";        foreach (array_keys($array) as $arr) {            if (!$firstControl) {                $sql .= ', ';            }            else {                $firstControl = false;            }            $sql .= $arr;        }        $sql .= " )";        return $sql;    }    public function CreateFunctionSql($functionName, $array = array())    {        $firstControl = true;        $sql = "Select " . $functionName . "( ";        foreach (array_keys($array) as $arr) {            if (!$firstControl) {                $sql .= ', ';            }            else {                $firstControl = false;            }            $sql .= $arr;        }        $sql .= " ) as result";        return $sql;    }    public function getOutParamsProcedure($sql, $array = array(), $get_table = false)    {        $query = '';        foreach ($array as $key => $value) {            if ($key[0] == '@') {                $query .= "SET " . $key . ' = ' . ($value !== null ? " '" . $value . "';" : "null;");            }        }        $sql = $query . $sql;        $sth = $this->prepare($sql);        foreach ($array as $key => $value) {            //	$key=str_replace('@',':',$key);            if ($key[0] == ':')                $sth->bindValue($key, $value);        }        $this->executeSth($sth, $sql, $array);        $this->UserLog($sql, json_encode(array_values($array), JSON_UNESCAPED_UNICODE));        $this->HasError($sql, $array, $sth);        $table_datas = $sth->fetchAll(PDO::FETCH_ASSOC);        $sth->closeCursor();        $sql = "select ";        $firstControl = true;        foreach ($array as $key => $value) {            if ($key[0] == '@') {                if (!$firstControl) {                    $sql .= ', ';                }                else {                    $firstControl = false;                }                $sql .= $key . ' as ' . substr($key, 1);            }        }        $sth = $this->prepare($sql);        $sth->execute();        $datas = $sth->fetchAll(PDO::FETCH_ASSOC);        $sth->closeCursor();        $datas = isset($datas) ? (count($datas) > 1 ? $datas : $datas[0]) : false;        return $get_table ? array('table' => $table_datas, 'params' => $datas) : $datas;    }    private function HasError($sql, $array, $sth)    {        $i = 0;        do {            $this->ErrorLog($sql, json_encode(array_values($array), JSON_UNESCAPED_UNICODE), $sth->errorInfo());            $sth->nextRowset();            $i++;        } while ($i < 5);//		do {//			$this->ErrorLog($sql, json_encode(array_values($array), JSON_UNESCAPED_UNICODE), $sth->errorInfo());//		} while ($sth->nextRowset());    }    private function ExecuteLog($note, $note1 = '', $time = 0)    {        global $CurrentUser;        $note1 = $note1 ?? '';        $note = $note . ' ' . $note1 ;        if (!$this->debug)            return;        $note_parts1 = explode('(', $note, 2);        $note_parts2 = explode(')', $note_parts1[1], 2);        $full_procedure_name = isset($note_parts1[0]) ? str_replace(array('CALL', ' '), array('', ''), $note_parts1[0]) : '';        if (strpos($full_procedure_name, 'PermissionUserPageSelect', 0) !== false) {            return;        }        $proc_name = explode('.', $full_procedure_name);        $query_db = isset($proc_name[1]) ? trim($proc_name[0]) : DB_NAME;        $proc_name = isset($proc_name[0]) ? trim($proc_name[isset($proc_name[1]) ? 1 : 0]) : '';        $proc_values = isset($note_parts2[1]) ? trim(str_replace(array('[', ']'), array('', ''), $note_parts2[1])) : '';        $array = array(            'executer_user' => isset($CurrentUser) ? $CurrentUser->id : null,            'execution_information' => date('Y-m-d h:i:s'),            'execution_time' => $time,            'execution_data' => sprintf('CALL %s.%s(%s)', $query_db, $proc_name, $proc_values),        );       LogModule::SetMysqlLog(str_replace('\\"', '"', json_encode($array, JSON_UNESCAPED_UNICODE)));    }    private function UserLog($note, $note1 = '')    {        global $CurrentUser, $currentIp;        if (!empty($note1))            $note = $note . ' ' . $note1;        $note_parts1 = explode('(', $note, 2);        $note_parts2 = explode(')', $note_parts1[1], 2);        $full_procedure_name = isset($note_parts1[0]) ? str_replace(array('CALL', ' '), array('', ''), $note_parts1[0]) : '';        if (strpos($full_procedure_name, 'PermissionUserPageSelect', 0) !== false) {            return;        }        $proc_name = explode('.', $full_procedure_name);        $query_db = isset($proc_name[1]) ? trim($proc_name[0]) : DB_NAME;        $proc_name = isset($proc_name[0]) ? trim($proc_name[isset($proc_name[1]) ? 1 : 0]) : '';        $proc_values = isset($note_parts2[1]) ? trim(str_replace(array('[', ']'), array('', ''), $note_parts2[1])) : '';//        if ($_SERVER['HTTP_USER_AGENT'] == 'ERKAY TEKNOLOJI 1.1' && !$testMode && $proc_name=='StudentSelectList') {//            _print($note);//            _print(sprintf('CALL %s.%s(%s)',$query_db,$proc_name,$proc_values));//            die();//        }        $array = array(            'executer_user' => $CurrentUser->id,            'executer_ip' => $currentIp,            'execution_information' => date('Y-m-d h:i:s'),            'execution_data' => sprintf('CALL %s.%s(%s)', $query_db, $proc_name, $proc_values),        );        SetMysqlUserLog(str_replace('\\"', '"', json_encode($array, JSON_UNESCAPED_UNICODE)));    }    private function ErrorLog($note, $note1 = '', $error = array())    {        $logAll = false;        if (!empty($note1))            $note = $note . ' ' . $note1;        if ($logAll || ($error[0] != 'HY000' && (!empty($error[1]) || $error[0] != '00000'))) {            //error log ekle            $note_parts1 = explode('(', $note);            $note_parts2 = explode(')', $note_parts1[1]);            $full_procedure_name = isset($note_parts1[0]) ? str_replace(array('CALL', ' '), array('', ''), $note_parts1[0]) : '';            $proc_name = explode('.', $full_procedure_name);            $query_db = isset($proc_name[1]) ? trim($proc_name[0]) : DB_NAME;            $proc_name = isset($proc_name[0]) ? trim($proc_name[isset($proc_name[1]) ? 1 : 0]) : '';            $proc_params = isset($note_parts2[0]) ? trim($note_parts2[0]) : '';            $proc_values = isset($note_parts2[1]) ? trim(str_replace(array('[', ']'), array('', ''), $note_parts2[1])) : '';            $array = array(                ':prm_employee_id' => $this->current_user_id,                ':prm_query_db' => $query_db,                ':prm_proc_name' => $proc_name,                ':prm_proc_params' => $proc_params,                ':prm_proc_values' => $proc_values,                ':prm_result_code' => $error[0],                ':prm_error_code' => $error[1],                ':prm_error_text' => $error[2],            );            //_print($array);            $json = json_encode($array);            LogModule::SetMysqErrorlLog($json);        }        return true;    }}